sys_script_client.script:
function onLoad() {
    // Read URL parameters for approval context
    var actionType = getUrlParameter('sysparm_action_type');
    var amount = getUrlParameter('sysparm_amount');

    // If both params are present, we're in approval context
    if (actionType && amount) {
        // Format amount with dollar sign and two decimal places
        var formattedAmount = parseFloat(amount).toFixed(2);
        var label = (actionType === 'deposit') ? 'deposit' : 'withdrawal';
        g_form.addInfoMessage('Approved ' + label + ' request for $' + formattedAmount);

        // Use setTimeout to ensure DOM is fully ready before hiding buttons
        setTimeout(function() {
            if (actionType === 'deposit') {
                // In deposit context: hide Withdraw Funds and Deactivate Account buttons
                hideButtonByOnclick('withdrawFunds');
                hideButtonByOnclick('deactivateAccount');
            } else if (actionType === 'withdrawal') {
                // In withdrawal context: hide Deposit Funds and Deactivate Account buttons
                hideButtonByOnclick('depositFunds');
                hideButtonByOnclick('deactivateAccount');
            }
        }, 500);
    }
    // If params not present, do nothing (normal behavior)

    function getUrlParameter(name) {
        var results = new RegExp('[\\?&]' + name + '=([^&#]*)').exec(window.location.href);
        return results ? decodeURIComponent(results[1]) : '';
    }

    function hideButtonByOnclick(fnName) {
        // Search DOM for buttons whose onclick attribute contains the function name
        var buttons = document.querySelectorAll('button[onclick], input[type="button"][onclick]');
        for (var i = 0; i < buttons.length; i++) {
            var onclickAttr = buttons[i].getAttribute('onclick') || '';
            if (onclickAttr.indexOf(fnName) >= 0) {
                buttons[i].style.display = 'none';
            }
        }
    }
}
